
  /* ============================================================
     Screen 3 — the evaluation sheet: what the recording and the two screens
     showed, against Nielsen's heuristics and B2B checkout practice.
     ============================================================ */
  var FINDINGS = [
    { sev: 4, h: "Error prevention", where: "Verification → Place Order", issue: "Stock and minimum-order checks run only when \"Place Order\" is pressed — after the buyer edited an address and uploaded documents. In the recording it fails with an \"Insufficient stock\" toast and the buyer is sent back to the cart to fix quantities, then must redo the checkout.", fix: "Pre-flight checks on entering checkout and again on submit, shown as a checklist. A change is resolved in place with a Confirmation Dialog (reduce / remove / back), never by bouncing the user. Try the \"Scenario: stock changes\" toggle." },
    { sev: 4, h: "Match with the real world", where: "Business documents", issue: "The three upload boxes give no sign of what is already on file, whether it was accepted, or what is still required — in the recording the licence is removed and re-uploaded to find out. Nothing says which formats or sizes are accepted until the file is rejected.", fix: "The same three zones, on the File Upload molecule: a document already on file shows as a card (name, size, date, Preview / Replace / Remove); an empty zone states Required or Optional and the accepted types; upload shows progress, then the card. Documents save to the account, so the next order starts with them on file." },
    { sev: 3, h: "Aesthetic & minimalist", where: "Personal ID document", issue: "Whatever file is chosen renders at full width — in the recording a personal photo, then a placeholder graphic — pushing the primary action a screen below the fold.", fix: "A 64 px thumbnail with name, size, View and Replace. Accepted types and the 10 MB limit are stated before the click, and the preview opens in a Drawer." },
    { sev: 3, h: "Visibility of system status", where: "Order created page", issue: "\"Thank you — your order has been placed successfully\" sits above \"Complete your payment\". Two states are announced at once; the buyer cannot tell whether anything is still required of them.", fix: "One status: \"Order received — awaiting your transfer\", a status pill, and a five-step progress that moves when the receipt is submitted." },
    { sev: 3, h: "Recognition over recall", where: "Bank details", issue: "IBAN, SWIFT and amount are given, but nothing says what to write on the transfer. Finance reconciles by amount and date, and a duplicate amount goes to the wrong order.", fix: "The order number is the payment reference, shown as a fact tile with its own copy button, and included in \"Copy all details\"." },
    { sev: 3, h: "User control & freedom", where: "Transaction receipt", issue: "\"Click on Track Your Order to upload the transaction receipt\" moves the upload to a dashboard modal that offers \"Skip for now\". The one action that completes the order is two screens away and optional.", fix: "The upload lives on the confirmation page with drag-and-drop, a real preview and Submit. Submitting advances the timeline; the dashboard remains a fallback." },
    { sev: 3, h: "Visibility of system status", where: "Verification page", issue: "No order summary, total, supplier or delivery slot on the page where the buyer commits; \"Place Order\" is a small button in the bottom-right under the document preview.", fix: "A sticky summary rail with the lines, totals and the primary action; on compact a fixed commit bar carries the total and the button." },
    { sev: 2, h: "Consistency & standards", where: "Saved details / address", issue: "Every saved value is rendered in orange (secondary/600) — decoration that reads as links, and measures 2.25:1 against white.", fix: "Labels in on-surface-variant, values in on-surface. Colour is reserved for status pills." },
    { sev: 2, h: "Flexibility & efficiency", where: "Branch details + Delivery address", issue: "Edit Details and Edit Address swap the saved values for a bare form with no validation, no unsaved-change guard and a Cancel that sits next to the primary; the map appears only in edit mode, so the \"pin is saved\" banner refers to something the buyer cannot see.", fix: "The same inline edit, on the Text Field, Phone Field and Select molecules: required marks, inline errors, Cancel · Save with the primary on the end, and Place Order refuses while an edit is open. The map pin is visible in the saved state too, with Move pin." },
    { sev: 2, h: "Visibility of system status", where: "Verification page", issue: "The payment method chosen on the review page (Highbase Payment) is invisible here, and its consequences — a 48-hour transfer, a receipt upload — are only discovered after the order exists.", fix: "The method is shown and switchable on the verification page, with what it implies stated in the option." },
    { sev: 2, h: "Match with the real world", where: "Order created page", issue: "Built for the person clicking, not the person paying: no way to hand the details to finance, no PDF, no deadline for the reservation.", fix: "Copy all details, Download instructions (PDF), Send to finance, and a \"Transfer by\" deadline tile. A purchase-order number is captured before the order is placed." },
    { sev: 2, h: "Consistency & standards", where: "Stepper", issue: "\"Step: Address & Documents\" in orange and a \"Step 2\" badge on Business Documents are the only progress cues; the buyer cannot see how many steps remain or where payment comes.", fix: "One stepper across the flow — Cart · Review · Verify & place order · Pay — with done / current / upcoming states." },
    { sev: 1, h: "Consistency & standards", where: "Order created page", issue: "Two filled buttons in two greens, \"Track Your Order\" and \"Go To Marketplace\", compete as the primary action.", fix: "One primary per state: submit the receipt, then track. Continue shopping is a ghost button." },
    { sev: 1, h: "Help & documentation", where: "Payment QR", issue: "\"Scan this QR code from your bank app\" does not say which apps, or what the scan pre-fills.", fix: "Names the apps (Benefit Pay, Fawri+) and states that the amount and reference are pre-filled." }
  ];

  function renderWhy(){
    var host = $("#screen-why");
    var counts = FINDINGS.reduce(function (m, f) { m[f.sev] = (m[f.sev] || 0) + 1; return m; }, {});
    host.innerHTML =
      '<h1 class="hb-headline-md">Where verification and payment lose orders</h1>' +
      '<p class="hb-body-md">Fourteen findings from the Loom recording (2:37, 10 Sep) and the two screens, scored on Nielsen\'s severity scale. Every fix is on the two screens in this prototype; the number in each row matches the annotation pin on the page.</p>' +
      '<div class="legend hb-body-sm"><span><span class="sev" data-sev="4">4</span> Catastrophic · ' + (counts[4] || 0) + '</span><span><span class="sev" data-sev="3">3</span> Major · ' + (counts[3] || 0) + '</span><span><span class="sev" data-sev="2">2</span> Minor · ' + (counts[2] || 0) + '</span><span><span class="sev" data-sev="1">1</span> Cosmetic · ' + (counts[1] || 0) + '</span></div>' +
      '<div class="hb-table-wrap"><div class="hb-table-scroll"><table class="hb-table"><thead><tr>' +
        '<th class="hb-th">Sev.</th><th class="hb-th">Heuristic</th><th class="hb-th">Where</th><th class="hb-th">What the recording shows</th><th class="hb-th">What the prototype does</th>' +
      '</tr></thead><tbody>' + FINDINGS.map(function (f, i) {
        return '<tr><td><span class="sev" data-sev="' + f.sev + '">' + f.sev + '</span></td><td class="hb-body-sm">' + f.h + '</td><td class="hb-body-sm">' + f.where + '</td><td class="hb-body-sm">' + f.issue + '</td><td class="hb-body-sm">' + f.fix + '</td></tr>';
      }).join('') + '</tbody></table></div></div>' +
      '<h2 class="hb-title-lg">What the voice note asked for</h2>' +
      '<p class="hb-body-md">The WhatsApp note (10 Sep, 15:08) says the cart, review and final cart are complete. The gap is the two pages that follow Confirm Order: the business-documents / ID upload, and the payment confirmation that "only confirms the order was made and shows bank details underneath" — "the flow is not clear, and I cannot do anything". It also notes who uses them: people running a business, often senior. That is why both screens here lead with one plain statement of where the buyer is, keep one primary action per state, and never ask for a document the account already holds.</p>' +
      '<h2 class="hb-title-lg">Practices this proposal follows</h2>' +
      '<p class="hb-body-md">Validate inventory before commitment and resolve conflicts in place (Baymard, checkout usability). Business verification as an account state, not a per-order upload (KYB once, re-verify on expiry). One visible status per page, with a progress model that moves on the buyer\'s action. Bank-transfer checkouts need a payment reference, a deadline and a hand-off to the payer. One primary action per state.</p>';
  }
